fn_generate_proposal_no.definition:
CREATE OR REPLACE FUNCTION ifms_budget.fn_generate_proposal_no()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_fy_code varchar(15);
BEGIN
  IF NEW.proposal_no IS NULL OR btrim(NEW.proposal_no) = '' THEN
    SELECT fy_code INTO v_fy_code
    FROM ifms_budget.financial_year
    WHERE financial_year_id = NEW.financial_year_id;

    IF v_fy_code IS NULL THEN
      RAISE EXCEPTION 'Financial year % not found for proposal numbering', NEW.financial_year_id;
    END IF;

    NEW.proposal_no := 'BGT-' || replace(v_fy_code, '-', '') || '-'
      || lpad(nextval('ifms_budget.proposal_number_seq')::text, 7, '0');
  END IF;
  RETURN NEW;
END;
$function$

fn_log_change.definition:
CREATE OR REPLACE FUNCTION ifms_budget.fn_log_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
            DECLARE
              v_pk text;
              v_changed_by bigint;
            BEGIN
              v_pk := COALESCE(to_jsonb(NEW)->>TG_ARGV[0], to_jsonb(OLD)->>TG_ARGV[0]);
              BEGIN
                v_changed_by := NULLIF(current_setting('app.user_id', true), '')::bigint;
              EXCEPTION WHEN invalid_text_representation THEN
                v_changed_by := NULL;
              END;

              INSERT INTO ifms_budget.audit_change_log
                (schema_name, table_name, operation, row_pk, old_data, new_data, changed_by)
              VALUES
                (TG_TABLE_SCHEMA, TG_TABLE_NAME, TG_OP, v_pk,
                 CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN to_jsonb(OLD) END,
                 CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN to_jsonb(NEW) END,
                 v_changed_by);
              RETURN COALESCE(NEW, OLD);
            END;
            $function$

fn_next_document_no.definition:
CREATE OR REPLACE FUNCTION ifms_budget.fn_next_document_no(p_sequence_key character varying, p_financial_year_id bigint DEFAULT NULL::bigint)
 RETURNS character varying
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_prefix varchar(20);
  v_number bigint;
  v_padding integer;
  v_fy varchar(15);
BEGIN
  UPDATE ifms_budget.document_number_sequence
     SET last_number = last_number + 1,
         updated_at = clock_timestamp()
   WHERE sequence_key = upper(p_sequence_key)
   RETURNING prefix, last_number, padding_length INTO v_prefix, v_number, v_padding;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Document sequence key % is not configured', p_sequence_key;
  END IF;

  IF p_financial_year_id IS NOT NULL THEN
    SELECT replace(fy_code, '-', '') INTO v_fy
    FROM ifms_budget.financial_year
    WHERE financial_year_id = p_financial_year_id;
  END IF;

  RETURN v_prefix || COALESCE(v_fy, to_char(current_date, 'YYYY')) || '-' || lpad(v_number::text, v_padding, '0');
END;
$function$

