fn_rev_audit_handler.definition:
CREATE OR REPLACE FUNCTION ifms_budget.fn_rev_audit_handler()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
            DECLARE
                v_old jsonb := NULL;
                v_new jsonb := NULL;
                v_pk text := NULL;
            BEGIN
                IF (TG_OP = 'DELETE') THEN
                    v_old := to_jsonb(OLD);
                    v_pk := COALESCE(
                        v_old->>'step_id',
                        v_old->>'template_id',
                        v_old->>'glossary_id',
                        v_old->>'recon_id', 
                        v_old->>'batch_id', 
                        v_old->>'voucher_id', 
                        v_old->>'refund_id', 
                        v_old->>'claim_id', 
                        v_old->>'exception_id', 
                        'UNKNOWN'
                    );
                    INSERT INTO ifms_budget.audit_change_log (schema_name, table_name, operation, row_pk, old_data, new_data, changed_by)
                    VALUES (TG_TABLE_SCHEMA, TG_TABLE_NAME, 'DELETE', v_pk, v_old, NULL, NULL);
                    RETURN OLD;
                ELSIF (TG_OP = 'UPDATE') THEN
                    v_old := to_jsonb(OLD);
                    v_new := to_jsonb(NEW);
                    v_pk := COALESCE(
                        v_new->>'step_id',
                        v_new->>'template_id',
                        v_new->>'glossary_id',
                        v_new->>'recon_id', 
                        v_new->>'batch_id', 
                        v_new->>'voucher_id', 
                        v_new->>'refund_id', 
                        v_new->>'claim_id', 
                        v_new->>'exception_id', 
                        'UNKNOWN'
                    );
                    INSERT INTO ifms_budget.audit_change_log (schema_name, table_name, operation, row_pk, old_data, new_data, changed_by)
                    VALUES (TG_TABLE_SCHEMA, TG_TABLE_NAME, 'UPDATE', v_pk, v_old, v_new, NULL);
                    RETURN NEW;
                ELSIF (TG_OP = 'INSERT') THEN
                    v_new := to_jsonb(NEW);
                    v_pk := COALESCE(
                        v_new->>'step_id',
                        v_new->>'template_id',
                        v_new->>'glossary_id',
                        v_new->>'recon_id', 
                        v_new->>'batch_id', 
                        v_new->>'voucher_id', 
                        v_new->>'refund_id', 
                        v_new->>'claim_id', 
                        v_new->>'exception_id', 
                        'UNKNOWN'
                    );
                    INSERT INTO ifms_budget.audit_change_log (schema_name, table_name, operation, row_pk, old_data, new_data, changed_by)
                    VALUES (TG_TABLE_SCHEMA, TG_TABLE_NAME, 'INSERT', v_pk, NULL, v_new, NULL);
                    RETURN NEW;
                END IF;
                RETURN NULL;
            END;
        $function$

fn_rev_calculate_delay_days.definition:
CREATE OR REPLACE FUNCTION ifms_budget.fn_rev_calculate_delay_days(p_payment_mode text, p_payment_date date, p_realisation_date date, p_remittance_date date, p_allowed_days integer DEFAULT 1)
 RETURNS TABLE(base_date date, base_date_type text, actual_days integer, delay_days integer)
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
    v_base date;
    v_type text;
    v_actual integer;
    v_delay integer;
BEGIN
    IF UPPER(p_payment_mode) IN ('CHEQUE', 'DD') THEN
        v_base := COALESCE(p_realisation_date, p_payment_date);
        v_type := 'REALISATION_DATE';
    ELSE
        v_base := p_payment_date;
        v_type := 'PAYMENT_DATE';
    END IF;

    v_actual := GREATEST(0, (p_remittance_date - v_base));
    v_delay := GREATEST(0, v_actual - p_allowed_days);

    RETURN QUERY SELECT v_base, v_type, v_actual, v_delay;
END;
$function$

fn_rev_compute_penal_interest.definition:
CREATE OR REPLACE FUNCTION ifms_budget.fn_rev_compute_penal_interest(p_principal numeric, p_annual_rate_pct numeric, p_delay_days integer, p_day_basis integer DEFAULT 365)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
BEGIN
    IF p_delay_days <= 0 OR p_principal <= 0 OR p_annual_rate_pct <= 0 THEN
        RETURN 0.00;
    END IF;
    RETURN ROUND((p_principal * (p_annual_rate_pct / 100.0) * p_delay_days) / p_day_basis, 2);
END;
$function$

fn_rev_next_seq.definition:
CREATE OR REPLACE FUNCTION ifms_budget.fn_rev_next_seq(p_sequence_key text, p_prefix text, p_fy text DEFAULT '2026-27'::text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_next bigint;
    v_formatted text;
BEGIN
    INSERT INTO ifms_budget.document_number_sequence (sequence_key, prefix, last_number, padding_length, updated_at)
    VALUES (p_sequence_key, p_prefix, 1, 6, clock_timestamp())
    ON CONFLICT (sequence_key) DO UPDATE
    SET last_number = ifms_budget.document_number_sequence.last_number + 1,
        updated_at = clock_timestamp()
    RETURNING last_number INTO v_next;

    v_formatted := p_prefix || '-' || p_fy || '-' || LPAD(v_next::text, 6, '0');
    RETURN v_formatted;
END;
$function$

