fn_unlock_budget_version.definition:
CREATE OR REPLACE FUNCTION ifms_budget.fn_unlock_budget_version(p_unlock_request_id bigint, p_approved_by bigint, p_remarks text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_request ifms_budget.budget_unlock_request%ROWTYPE;
BEGIN
  SELECT * INTO v_request
  FROM ifms_budget.budget_unlock_request
  WHERE unlock_request_id = p_unlock_request_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Unlock request % does not exist', p_unlock_request_id;
  END IF;
  IF v_request.request_status <> 'SUBMITTED' THEN
    RAISE EXCEPTION 'Only submitted unlock requests may be approved';
  END IF;

  UPDATE ifms_budget.budget_unlock_request
  SET request_status = 'APPROVED', approved_by = p_approved_by, approved_at = clock_timestamp(), approval_remarks = p_remarks,
      unlock_from = clock_timestamp(), updated_at = clock_timestamp()
  WHERE unlock_request_id = p_unlock_request_id;

  UPDATE ifms_budget.budget_version
  SET is_locked = false, version_status = 'FINAL', lock_reason = NULL, updated_by = p_approved_by, updated_at = clock_timestamp()
  WHERE budget_version_id = v_request.budget_version_id;
END;
$function$

fn_validate_coa_hierarchy.definition:
CREATE OR REPLACE FUNCTION ifms_budget.fn_validate_coa_hierarchy()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_parent_id bigint;
BEGIN
  SELECT major_head_id INTO v_parent_id
  FROM ifms_budget.sub_major_head
  WHERE sub_major_head_id = NEW.sub_major_head_id;
  IF v_parent_id IS NULL OR v_parent_id <> NEW.major_head_id THEN
    RAISE EXCEPTION 'Invalid Chart of Account hierarchy: sub-major head does not belong to selected major head';
  END IF;

  SELECT sub_major_head_id INTO v_parent_id
  FROM ifms_budget.minor_head
  WHERE minor_head_id = NEW.minor_head_id;
  IF v_parent_id IS NULL OR v_parent_id <> NEW.sub_major_head_id THEN
    RAISE EXCEPTION 'Invalid Chart of Account hierarchy: minor head does not belong to selected sub-major head';
  END IF;

  SELECT minor_head_id INTO v_parent_id
  FROM ifms_budget.sub_head
  WHERE sub_head_id = NEW.sub_head_id;
  IF v_parent_id IS NULL OR v_parent_id <> NEW.minor_head_id THEN
    RAISE EXCEPTION 'Invalid Chart of Account hierarchy: sub head does not belong to selected minor head';
  END IF;

  SELECT sub_head_id INTO v_parent_id
  FROM ifms_budget.detail_head
  WHERE detail_head_id = NEW.detail_head_id;
  IF v_parent_id IS NULL OR v_parent_id <> NEW.sub_head_id THEN
    RAISE EXCEPTION 'Invalid Chart of Account hierarchy: detail head does not belong to selected sub head';
  END IF;

  SELECT detail_head_id INTO v_parent_id
  FROM ifms_budget.object_head
  WHERE object_head_id = NEW.object_head_id;
  IF v_parent_id IS NULL OR v_parent_id <> NEW.detail_head_id THEN
    RAISE EXCEPTION 'Invalid Chart of Account hierarchy: object head does not belong to selected detail head';
  END IF;
  RETURN NEW;
END;
$function$

fn_validate_reappropriation_balance.definition:
CREATE OR REPLACE FUNCTION ifms_budget.fn_validate_reappropriation_balance()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_debit_total numeric(18,2);
  v_credit_total numeric(18,2);
  v_id bigint;
BEGIN
  v_id := COALESCE(NEW.reappropriation_id, OLD.reappropriation_id);
  SELECT COALESCE(SUM(CASE WHEN line_role = 'DEBIT' THEN line_amount ELSE 0 END),0),
         COALESCE(SUM(CASE WHEN line_role = 'CREDIT' THEN line_amount ELSE 0 END),0)
    INTO v_debit_total, v_credit_total
  FROM ifms_budget.reappropriation_line
  WHERE reappropriation_id = v_id;
  IF v_debit_total > 0 AND v_credit_total > 0 AND v_debit_total <> v_credit_total THEN
    RAISE EXCEPTION 'Re-appropriation debit total (%) and credit total (%) must be equal', v_debit_total, v_credit_total;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$function$

fn_validate_submission_phasing.definition:
CREATE OR REPLACE FUNCTION ifms_budget.fn_validate_submission_phasing()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_total_phase numeric(18,2);
  v_proposed numeric(18,2);
  v_line_id bigint;
BEGIN
  v_line_id := COALESCE(NEW.submission_line_id, OLD.submission_line_id);
  SELECT COALESCE(SUM(phase_amount), 0) INTO v_total_phase
  FROM ifms_budget.budget_submission_phasing
  WHERE submission_line_id = v_line_id;
  SELECT proposed_be INTO v_proposed
  FROM ifms_budget.budget_submission_line
  WHERE submission_line_id = v_line_id;
  IF v_proposed IS NOT NULL AND v_total_phase > v_proposed THEN
    RAISE EXCEPTION 'Monthly phasing total (%) cannot exceed proposed BE (%) for submission line %', v_total_phase, v_proposed, v_line_id;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$function$

sp_rev_create_booking_vouchers.definition:
CREATE OR REPLACE PROCEDURE ifms_budget.sp_rev_create_booking_vouchers(IN p_user_id bigint, IN p_pao_code character varying DEFAULT 'PAO21'::character varying)
 LANGUAGE plpgsql
AS $procedure$
        DECLARE
            v_item RECORD;
            v_vch_id bigint;
            v_vch_no character varying(50);
            v_clearing_coa_id bigint;
            v_penal_coa_id bigint;
            v_rev_coa_id bigint;
            v_amount numeric(17,2);
            v_next_sr bigint;
            v_org_id bigint := 1;
            v_branch_id bigint := 1;
        BEGIN
            SELECT organization_id, branch_id INTO v_org_id, v_branch_id FROM ifms_budget.branch LIMIT 1;
            IF v_org_id IS NULL THEN v_org_id := 1; v_branch_id := 1; END IF;

            -- Default Dr Suspense/Clearing Head (8658 Remittance in Transit)
            SELECT suspense_head_id, penal_interest_head_id INTO v_clearing_coa_id, v_penal_coa_id 
            FROM ifms_budget.rev_system_config WHERE config_id = 1;

            IF v_clearing_coa_id IS NULL THEN
                SELECT coa_id INTO v_clearing_coa_id FROM ifms_budget.chart_of_account WHERE coa_code LIKE '8658%' LIMIT 1;
            END IF;
            IF v_penal_coa_id IS NULL THEN
                SELECT coa_id INTO v_penal_coa_id FROM ifms_budget.chart_of_account WHERE coa_code = '8658-00-102-01-00-02' LIMIT 1;
                IF v_penal_coa_id IS NULL THEN v_penal_coa_id := v_clearing_coa_id; END IF;
            END IF;

            FOR v_item IN 
                SELECT res.recon_id, res.challan_no, res.payer_name, res.pao_code, res.receipt_head,
                       COALESCE(NULLIF(res.portal_total, 0), NULLIF(res.bank_total, 0), NULLIF(res.rbi_total, 0), 100.00)::numeric(17,2) as vch_amount,
                       COALESCE(res.penal_interest_amount, 0.00)::numeric(17,2) as penal_amount,
                       s.department_id, s.default_receipt_head_id
                FROM ifms_budget.rev_recon_result res
                LEFT JOIN ifms_budget.rev_revenue_source s ON s.source_code = res.revenue_source
                WHERE res.status = 'Matched' 
                  AND (p_pao_code IS NULL OR res.pao_code = p_pao_code)
                  AND res.booking_status IN ('UNBOOKED', 'READY_FOR_BOOKING')
            LOOP
                v_amount := v_item.vch_amount;
                IF v_amount <= 0 THEN v_amount := 100.00; END IF;

                -- Credit Revenue Head from source or receipt_head
                IF v_item.default_receipt_head_id IS NOT NULL THEN
                    v_rev_coa_id := v_item.default_receipt_head_id;
                ELSE
                    SELECT coa_id INTO v_rev_coa_id FROM ifms_budget.chart_of_account WHERE coa_code = v_item.receipt_head LIMIT 1;
                    IF v_rev_coa_id IS NULL THEN
                        SELECT coa_id INTO v_rev_coa_id FROM ifms_budget.chart_of_account LIMIT 1;
                    END IF;
                END IF;

                v_vch_no := ifms_budget.fn_rev_next_seq('VOUCHER_SEQ', 'VR', '2026-27');
                IF v_vch_no IS NULL OR v_vch_no = '' THEN
                    v_vch_no := 'VR-' || to_char(CURRENT_DATE, 'YYYYMMDD') || '-' || lpad(v_item.recon_id::text, 4, '0');
                END IF;

                -- Row 1: Principal Gross Amount (sr_no = 1)
                INSERT INTO ifms_budget.account_voucher (
                    sr_no, voucher_no, recon_id, voucher_date, voucher_type, financial_year, pao_code,
                    amount, debit_coa_id, credit_coa_id, department_id,
                    narration, status, prepared_by, prepared_at,
                    organization_id, org_branch_id, created_by, updated_by, workflow_status
                ) VALUES (
                    1, v_vch_no, v_item.recon_id, CURRENT_DATE, 'REVENUE_RECEIPT', '2026-27', v_item.pao_code,
                    v_amount, v_clearing_coa_id, v_rev_coa_id, v_item.department_id,
                    'Receipt booked upon 3-way reconciliation match for Challan ' || COALESCE(v_item.challan_no, '') || ' (' || COALESCE(v_item.payer_name, 'Payer') || ')',
                    'Draft', p_user_id, clock_timestamp(),
                    v_org_id, v_branch_id, p_user_id, p_user_id, 'ACTIVE'
                ) RETURNING voucher_id INTO v_vch_id;

                -- Row 2: Penal Interest Amount (sr_no = 2) if penal interest accrued
                IF v_item.penal_amount > 0 THEN
                    INSERT INTO ifms_budget.account_voucher (
                        sr_no, voucher_no, recon_id, voucher_date, voucher_type, financial_year, pao_code,
                        amount, debit_coa_id, credit_coa_id, department_id,
                        narration, status, prepared_by, prepared_at,
                        organization_id, org_branch_id, created_by, updated_by, workflow_status
                    ) VALUES (
                        2, v_vch_no, v_item.recon_id, CURRENT_DATE, 'REVENUE_RECEIPT', '2026-27', v_item.pao_code,
                        v_item.penal_amount, v_penal_coa_id, v_rev_coa_id, v_item.department_id,
                        'Penal interest remittance for SLA delay on Challan ' || COALESCE(v_item.challan_no, ''),
                        'Draft', p_user_id, clock_timestamp(),
                        v_org_id, v_branch_id, p_user_id, p_user_id, 'ACTIVE'
                    );
                END IF;

                UPDATE ifms_budget.rev_recon_result SET booking_status = 'DRAFT_VOUCHER' WHERE recon_id = v_item.recon_id;
            END LOOP;
        END;
        $procedure$
